import * as React from "react";
import {
  Dialog as D,
  AlertDialog as A,
  Popover as P,
  Tooltip as T,
  HoverCard as H,
  Toast as RT,
} from "radix-ui";
import { X } from "lucide-react";
import { Button } from "./basic";
import { cx } from "./utils";
type ModalProps = {
  trigger?: React.ReactElement;
  title: string;
  description: string;
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (v: boolean) => void;
  footer?: React.ReactNode;
  placement?: "center" | "right" | "bottom";
};
export function Modal({
  trigger,
  title,
  description,
  children,
  open,
  onOpenChange,
  footer,
  placement = "center",
}: ModalProps) {
  return (
    <D.Root open={open} onOpenChange={onOpenChange}>
      {trigger && <D.Trigger asChild>{trigger}</D.Trigger>}
      <D.Portal>
        <D.Overlay className="a-overlay" />
        <D.Content
          className={cx(
            "a-modal-content fixed z-50 flex max-h-[90dvh] flex-col border border-line bg-card text-ink shadow-xl outline-none",
            placement === "center"
              ? "left-1/2 top-1/2 w-[min(560px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 rounded-2xl"
              : placement === "right"
                ? "right-0 top-0 h-dvh max-h-dvh w-[min(460px,100%)]"
                : "bottom-0 left-0 right-0 max-h-[85dvh] rounded-t-2xl",
          )}
        >
          <div className="border-b border-line px-6 py-5 pe-14">
            <D.Title className="font-editorial text-2xl">{title}</D.Title>
            <D.Description className="mt-2 text-sm text-muted">
              {description}
            </D.Description>
          </div>
          <div className="min-h-0 overflow-y-auto overscroll-contain p-5 sm:p-6">{children}</div>
          {footer && (
            <div className="flex flex-wrap justify-end gap-3 border-t border-line p-5">
              {footer}
            </div>
          )}
          <D.Close
            aria-label="Close dialog"
            className="a-close absolute end-3 top-3 flex size-11 items-center justify-center rounded-md hover:bg-surface"
          >
            <X className="size-4" />
          </D.Close>
        </D.Content>
      </D.Portal>
    </D.Root>
  );
}
export const Dialog = Modal;
export function Sheet(props: Omit<ModalProps, "placement">) {
  return <Modal {...props} placement="right" />;
}
export function Drawer(props: Omit<ModalProps, "placement">) {
  return <Modal {...props} placement="bottom" />;
}
export function AlertDialog({
  trigger,
  title,
  description,
  onConfirm,
  confirmLabel = "Confirm",
}: {
  trigger: React.ReactElement;
  title: string;
  description: string;
  onConfirm: () => void;
  confirmLabel?: string;
}) {
  return (
    <A.Root>
      <A.Trigger asChild>{trigger}</A.Trigger>
      <A.Portal>
        <A.Overlay className="a-overlay" />
        <A.Content className="a-modal-content fixed left-1/2 top-1/2 z-50 max-h-[90dvh] w-[min(480px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-2xl border border-line bg-card p-6 text-ink shadow-xl">
          <A.Title className="font-editorial text-2xl">{title}</A.Title>
          <A.Description className="my-4 text-sm leading-relaxed text-muted">
            {description}
          </A.Description>
          <div className="flex flex-wrap justify-end gap-3">
            <A.Cancel asChild>
              <Button tone="outline">Cancel</Button>
            </A.Cancel>
            <A.Action asChild>
              <Button tone="danger" onClick={onConfirm}>
                {confirmLabel}
              </Button>
            </A.Action>
          </div>
        </A.Content>
      </A.Portal>
    </A.Root>
  );
}
export function Popover({
  trigger,
  children,
  label,
}: {
  trigger: React.ReactElement;
  children: React.ReactNode;
  label: string;
}) {
  return (
    <P.Root>
      <P.Trigger asChild>{trigger}</P.Trigger>
      <P.Portal>
        <P.Content
          aria-label={label}
          sideOffset={8}
          className="a-popup w-72 p-5"
        >
          {children}
          <P.Close
            aria-label="Close popover"
            className="absolute end-1 top-1 p-1"
          >
            <X className="size-3" />
          </P.Close>
        </P.Content>
      </P.Portal>
    </P.Root>
  );
}
export function Tooltip({
  children,
  content,
}: {
  children: React.ReactElement;
  content: string;
}) {
  return (
    <T.Provider delayDuration={250}>
      <T.Root>
        <T.Trigger asChild>{children}</T.Trigger>
        <T.Portal>
          <T.Content
            sideOffset={6}
            className="z-[60] rounded-md bg-ink px-3 py-2 text-xs text-paper"
          >
            {content}
            <T.Arrow className="fill-ink" />
          </T.Content>
        </T.Portal>
      </T.Root>
    </T.Provider>
  );
}
export function HoverCard({
  trigger,
  children,
}: {
  trigger: React.ReactElement;
  children: React.ReactNode;
}) {
  return (
    <H.Root>
      <H.Trigger asChild>{trigger}</H.Trigger>
      <H.Portal>
        <H.Content sideOffset={8} className="a-popup w-72 p-5">
          {children}
        </H.Content>
      </H.Portal>
    </H.Root>
  );
}
export function Toast({open,onOpenChange,title,description,duration=5000}:{open:boolean;onOpenChange:(open:boolean)=>void;title:string;description?:string;duration?:number}){
 return <RT.Provider swipeDirection="right" duration={duration}><RT.Root open={open} onOpenChange={onOpenChange} className="rounded-xl border border-line bg-card p-5 text-ink shadow-xl"><RT.Title className="font-medium">{title}</RT.Title>{description&&<RT.Description className="mt-1 text-sm text-muted">{description}</RT.Description>}<RT.Close className="mt-3 text-sm underline">Dismiss</RT.Close></RT.Root><RT.Viewport className="fixed bottom-4 right-4 z-[70] m-0 w-[min(360px,calc(100%-32px))] list-none outline-none"/></RT.Provider>
}
export function ToastDemo(){const [open,setOpen]=React.useState(false);return <><Button tone="outline" onClick={()=>setOpen(true)}>Show notification</Button><Toast open={open} onOpenChange={setOpen} title="Changes saved" description="Your local example has been updated."/></>}

import * as React from "react";
import { LoaderCircle } from "lucide-react";
import { cx } from "./utils";
export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  tone?: "primary" | "secondary" | "outline" | "quiet" | "danger" | "accent";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "primary",
      size = "md",
      loading = false,
      disabled,
      children,
      className,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        ref={ref}
        type={type}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        className={cx(
          "a-button relative",
          {
            "bg-ink text-paper hover:bg-ink/85": tone === "primary",
            "bg-surface text-ink hover:bg-surface/70": tone === "secondary",
            "border border-control bg-transparent text-ink": tone === "outline",
            "bg-transparent text-ink hover:bg-surface": tone === "quiet",
            "bg-danger text-on-danger": tone === "danger",
            "bg-gold text-[#181818]": tone === "accent",
          },
          {
            "min-h-11 sm:min-h-9 px-3 text-xs": size === "sm",
            "min-h-11 px-4 text-sm": size === "md",
            "min-h-13 px-6 text-base": size === "lg",
          },
          loading && "disabled:opacity-100",
          className,
        )}
        {...props}
      >
        <span
          className="inline-flex min-w-0 items-center justify-center gap-2"
          style={{ opacity: loading ? 0 : undefined }}
        >
          {children}
        </span>
        {loading && (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 flex items-center justify-center"
          >
            <LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" />
          </span>
        )}
      </button>
    );
  },
);
export function Badge({
  tone = "neutral",
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLSpanElement> & {
  tone?: "neutral" | "success" | "warning" | "danger";
}) {
  return (
    <span
      className={cx(
        "inline-flex rounded-full px-2.5 py-1 text-xs font-medium",
        {
          "bg-surface text-ink": tone === "neutral",
          "bg-success/10 text-success": tone === "success",
          "bg-gold/20 text-ink": tone === "warning",
          "bg-danger/10 text-danger": tone === "danger",
        },
        className,
      )}
      {...props}
    >
      {children}
    </span>
  );
}
export function Card({
  className,
  ...props
}: React.HTMLAttributes<HTMLElement>) {
  return (
    <article
      className={cx("rounded-xl border border-line bg-card p-6", className)}
      {...props}
    />
  );
}
export function CardHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("mb-5 space-y-2", className)} {...props} />;
}
export function CardTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={cx("text-xl font-medium tracking-tight", className)}
      {...props}
    />
  );
}
export function CardDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cx("text-sm leading-relaxed text-muted", className)}
      {...props}
    />
  );
}
export function CardFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cx("mt-6 flex flex-wrap items-center gap-3", className)}
      {...props}
    />
  );
}
export const Separator = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLHRElement>) => (
  <hr className={cx("my-5 border-line", className)} {...props} />
);
export function Skeleton({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      aria-hidden
      className={cx(
        "h-4 rounded bg-surface animate-pulse motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  );
}
export function Spinner({ label = "Loading" }: { label?: string }) {
  return (
    <span role="status" className="inline-flex items-center gap-2 text-sm">
      <LoaderCircle
        className="size-4 animate-spin motion-reduce:animate-none"
        aria-hidden
      />
      {label}
    </span>
  );
}
export function Alert({
  title,
  children,
  tone = "info",
}: {
  title: string;
  children?: React.ReactNode;
  tone?: "info" | "error" | "success";
}) {
  return (
    <div
      role={tone === "error" ? "alert" : "status"}
      className={cx(
        "rounded-xl border p-4 text-sm",
        tone === "error"
          ? "border-danger/40 bg-danger/5"
          : tone === "success"
            ? "border-success/40 bg-success/5"
            : "border-line bg-surface/50",
      )}
    >
      <p className="font-semibold">{title}</p>
      {children && <div className="mt-2 leading-relaxed">{children}</div>}
    </div>
  );
}
export function Empty({
  title,
  children,
  action,
}: {
  title: string;
  children?: React.ReactNode;
  action?: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-dashed border-line p-10 text-center">
      <h3 className="font-editorial text-2xl">{title}</h3>
      <div className="mx-auto my-4 max-w-sm text-sm text-muted">{children}</div>
      {action}
    </div>
  );
}
export function Progress({ value, label }: { value: number; label: string }) {
  const current = Math.max(0, Math.min(100, value));
  return (
    <div>
      <div className="mb-2 flex justify-between text-sm">
        <span>{label}</span>
        <span>{current}%</span>
      </div>
      <progress
        aria-label={label}
        value={current}
        max={100}
        className="h-2 w-full overflow-hidden rounded-full accent-terracotta"
      />
    </div>
  );
}
export function Avatar({ src, name }: { src?: string; name: string }) {
  const [failed, setFailed] = React.useState(false);
  return (
    <span
      className="inline-flex size-10 items-center justify-center overflow-hidden rounded-full bg-surface text-sm font-semibold"
      role="img"
      aria-label={name}
    >
      {src && !failed ? (
        <img
          src={src}
          alt=""
          onError={() => setFailed(true)}
          className="size-full object-cover"
        />
      ) : (
        name
          .split(" ")
          .map((n) => n[0])
          .slice(0, 2)
          .join("")
      )}
    </span>
  );
}
export function AspectRatio({
  ratio = 16 / 9,
  children,
  className,
}: {
  ratio?: number;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div
      style={{ aspectRatio: ratio }}
      className={cx("overflow-hidden rounded-xl", className)}
    >
      {children}
    </div>
  );
}
export const Kbd = ({ children }: { children: React.ReactNode }) => (
  <kbd className="rounded border border-line bg-surface px-1.5 py-0.5 font-mono text-xs">
    {children}
  </kbd>
);
export const ButtonGroup = ({
  children,
  label,
}: {
  children: React.ReactNode;
  label: string;
}) => (
  <div role="group" aria-label={label} className="flex flex-wrap gap-2">
    {children}
  </div>
);
export function Item({
  title,
  description,
  action,
}: {
  title: string;
  description?: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-4 border-b border-line py-4">
      <div>
        <p className="font-medium">{title}</p>
        {description && <p className="text-sm text-muted">{description}</p>}
      </div>
      {action}
    </div>
  );
}
export function Typography({
  children,
  as: Tag = "p",
  editorial = false,
  className,
}: {
  children: React.ReactNode;
  as?: "h1" | "h2" | "h3" | "p";
  editorial?: boolean;
  className?: string;
}) {
  return (
    <Tag
      className={cx(
        editorial ? "font-editorial" : "font-sans",
        Tag === "h1"
          ? "text-5xl leading-tight tracking-tight"
          : Tag === "h2"
            ? "text-3xl tracking-tight"
            : Tag === "h3"
              ? "text-xl"
              : "leading-relaxed",
        className,
      )}
    >
      {children}
    </Tag>
  );
}
export function Direction({
  dir,
  children,
}: {
  dir: "ltr" | "rtl";
  children: React.ReactNode;
}) {
  return <div dir={dir}>{children}</div>;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export const cx = (...values: ClassValue[]) => twMerge(clsx(values));

@import "tailwindcss";
@source "./**/*.{ts,tsx}";
@theme {
  --color-paper: #f4f1e9;
  --color-ink: #20201d;
  --color-muted: #656158;
  --color-line: #d2ccc0;
  --color-control: #898d80;
  --color-surface: #e8e3d8;
  --color-card: #faf8f2;
  --color-terracotta: #ac4333;
  --color-gold: #edbd52;
  --color-danger: #a32925;
  --color-on-danger: #ffffff;
  --color-success: #326145;
  --color-chart-3: #b4bdb0;
  --color-chart-4: #cfc5ad;
  --color-chart-5: #8b9fa2;
  --radius-lg: 9px;
  --radius-xl: 16px;
  --radius-2xl: 22px;
  --font-sans: "DM Sans Variable", Arial, sans-serif;
  --font-editorial: "Lora Variable", Georgia, serif;
}
@layer base {
  * {
    border-color: var(--color-line);
  }
  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
    margin: 0;
    -webkit-font-smoothing: antialiased;
  }
  button:not(:disabled),
  summary {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid var(--color-terracotta);
    outline-offset: 4px;
  }
}
@layer components {
  .a-button {
    @apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-[background-color,color,border-color,box-shadow,transform] disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4 active:translate-y-px;
    letter-spacing: -0.015em;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }
  .a-input {
    @apply min-h-10 w-full rounded-lg border border-line bg-paper/50 px-3 py-2 text-sm text-ink shadow-xs placeholder:text-muted/75 disabled:opacity-50 aria-invalid:border-danger focus-visible:bg-card transition-colors;
  }
  .a-overlay {
    @apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs;
  }
  .a-popup {
    @apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl;
    max-width: calc(100vw - 24px);
    max-height: min(
      80dvh,
      var(--radix-popover-content-available-height, 80dvh)
    );
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--color-menu, var(--color-card));
  }
}
.a-modal-content {
  overflow-wrap: anywhere;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.a-input {
  min-width: 0;
}
progress {
  appearance: none;
  height: 8px;
  background: var(--color-surface);
}
progress::-webkit-progress-bar {
  background: var(--color-surface);
  border-radius: 100px;
}
progress::-webkit-progress-value {
  background: var(--color-terracotta);
  border-radius: 100px;
}
progress::-moz-progress-bar {
  background: var(--color-terracotta);
  border-radius: 100px;
}
.a-calendar {
  font-family: var(--font-sans);
  font-size: 13px;
  width: 100%;
  max-width: 330px;
  --rdp-accent-color: var(--color-terracotta);
}
.a-calendar table {
  border-collapse: separate;
  border-spacing: 2px;
  width: 100%;
  table-layout: fixed;
}
.a-calendar th {
  font-size: 10px;
  font-weight: 400;
  color: var(--color-muted);
  height: 28px;
}
.a-calendar td {
  padding: 0;
  text-align: center;
}
.a-calendar button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  width: 100%;
  min-height: 36px;
  border-radius: 7px;
  touch-action: manipulation;
}
.a-calendar button:hover {
  background: var(--color-surface);
}
.a-calendar [aria-selected="true"] button {
  background: var(--color-ink);
  color: var(--color-paper);
}
.a-calendar nav {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 10px;
}
.a-calendar nav button {
  width: 44px;
  height: 44px;
}
.a-calendar svg {
  width: 16px;
  height: 16px;
}
.a-calendar button:disabled {
  opacity: 0.35;
}
@media (max-width: 640px), (pointer: coarse) {
  .a-button {
    min-height: 44px;
    min-width: 44px;
  }
  .a-input {
    min-height: 44px;
    font-size: 16px;
  }
  [role="tab"],
  [role="menuitem"] {
    min-height: 44px;
  }
}
[data-theme="dark"] {
  --color-paper: #191a18;
  --color-ink: #eeeade;
  --color-muted: #b8b3a8;
  --color-line: #45463f;
  --color-control: #7b8371;
  --color-surface: #30312c;
  --color-card: #22241f;
  --color-terracotta: #e69477;
  --color-danger: #f2938c;
  --color-on-danger: #28120f;
  --color-success: #8fc8a4;
  --color-chart-3: #788b76;
  --color-chart-4: #a99b77;
  --color-chart-5: #7d9ca2;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
